                    sizeof(cRSubLoc) / sizeof(unsigned int);
            } while (lane
                < (int)(sizeof(runtime_cells[0]) / sizeof(runtime_cells[0][0])));

            ++row_index;
        } while (row_index < runtime_row_count);
    }
}

